UPDATE payment_authorization SET state_json=#{stateJson},version=#{version},status=#{status},active_business_id=#{activeBusiness},updated_at=#{updatedAt},debit_account_key=#{debitAccountKey}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND status=#{expectedStatus} AND terms_json=#{termsJson} AND decision_json=#{decisionJson}
AND ((version=1 AND debit_account_key IS NULL) OR debit_account_key=#{value13})
AND due_date IS NOT DISTINCT FROM #{dueDate}

mapper.select:

SELECT p.* FROM payment_authorization p WHERE p.tenant_id=#{argument1} AND p.legal_entity_id IN (SELECT l.id FROM organization_directory o
JOIN organization_person p ON p.tenant_id=o.tenant_id AND p.active=TRUE
JOIN organization_appointment a ON a.tenant_id=p.tenant_id AND a.person_id=p.id AND a.active=TRUE
JOIN organization_unit d ON d.tenant_id=a.tenant_id AND d.id=a.department_id AND d.active=TRUE AND d.kind='DEPARTMENT'
JOIN organization_unit j ON j.tenant_id=a.tenant_id AND j.id=a.position_id AND j.active=TRUE AND j.kind='POSITION' AND j.legal_entity_id=d.legal_entity_id
JOIN organization_unit l ON l.tenant_id=d.tenant_id AND l.id=d.legal_entity_id AND l.active=TRUE AND l.kind='LEGAL_ENTITY'
WHERE o.tenant_id=#{argument2} AND p.subject=#{argument3}
) AND p.legal_entity_id=#{argument4} AND p.debit_account_key IS NULL AND p.debit_account_key=#{argument5} AND p.due_date IS NULL AND p.due_date>=#{argument6} AND p.due_date<=#{argument7} AND (p.due_date>#{argument8} OR p.due_date IS NULL OR (p.due_date=#{argument9} AND (p.authorized_at<#{argument10} OR (p.authorized_at=#{argument11} AND p.id<#{argument12})))) AND p.due_date IS NULL AND (p.authorized_at<#{argument13} OR (p.authorized_at=#{argument14} AND p.id<#{argument15})) ORDER BY p.due_date ASC NULLS LAST,p.authorized_at DESC,p.id DESCp.authorized_at DESC,p.id DESC LIMIT #{argument16}


SELECT COUNT(*) FROM payment_authorization p WHERE p.tenant_id=#{argument1} AND p.legal_entity_id IN (SELECT l.id FROM organization_directory o
JOIN organization_person p ON p.tenant_id=o.tenant_id AND p.active=TRUE
JOIN organization_appointment a ON a.tenant_id=p.tenant_id AND a.person_id=p.id AND a.active=TRUE
JOIN organization_unit d ON d.tenant_id=a.tenant_id AND d.id=a.department_id AND d.active=TRUE AND d.kind='DEPARTMENT'
JOIN organization_unit j ON j.tenant_id=a.tenant_id AND j.id=a.position_id AND j.active=TRUE AND j.kind='POSITION' AND j.legal_entity_id=d.legal_entity_id
JOIN organization_unit l ON l.tenant_id=d.tenant_id AND l.id=d.legal_entity_id AND l.active=TRUE AND l.kind='LEGAL_ENTITY'
WHERE o.tenant_id=#{argument2} AND p.subject=#{argument3}
) AND p.legal_entity_id=#{argument4} AND p.debit_account_key IS NULL AND p.debit_account_key=#{argument5} AND p.due_date IS NULL AND p.due_date>=#{argument6} AND p.due_date<=#{argument7}
